fragment.source:
// Drifting stage smoke: smooth layered waves, no hashing, so it has no edges.
float smoke(vec2 p,float t){
 vec2 q=p*vec2(1.6,2.2)+vec2(.2*sin(t*.05),-t*.08);
 float n=0.0,amp=.5;
 mat2 turn=mat2(.8,-.6,.6,.8);
 for(int i=0;i<4;i++){
  q+=.35*vec2(sin(q.y*1.3+t*.07),cos(q.x*1.1-t*.05));
  n+=amp*(.5+.5*sin(q.x*1.7+1.3*sin(q.y*1.2)));
  q=turn*q*1.9;amp*=.5;
 }
 return n/.9375;
}
// Beam directions do not depend on the pixel: the frame stage computes them once.
vec3 fan(vec2 p,vec2 o,int first,float count,float t,float side,float pix){
 vec3 acc=vec3(0.0);
 vec2 v=p-o;
 for(int i=0;i<12;i++){
  float fi=float(i);
  if(fi>=count)break;
  vec2 d=vrchFrameData(first+i).xy;
  float along=dot(v,d);
  if(along<=-.02)continue;
  float start=smoothstep(-.02,.03,along);
  along=max(along,0.0);
  float perp=abs(v.x*d.y-v.y*d.x);
  float w=max(pix*.55,.0004+along*.0007);
  float fade=(.25+.75*exp(-along*1.1))*start;
  acc.x+=exp(-perp*perp/(w*w))*fade;
  acc.y+=exp(-perp/(.006+along*.01))*fade;
  float g=max(sin(along*38.0-t*9.0+fi*2.9+side),0.0),g2=g*g,g4=g2*g2,g8=g4*g4,g16=g8*g8;
  acc.z+=exp(-perp*perp/(w*w))*uParam_sparkle*(g16*g8*g4)*fade;
 }
 return acc;
}
float beamCount(){return clamp(floor(uParam_beams+.5),1.0,12.0);}
// Centre angle of the left (side 0) or right (side 1) fan: an automatic scan,
// or toward the hand on that side.
float fanCenter(int side,float t){
 float aspect=iResolution.x/iResolution.y;
 vec2 oL=vec2(-.33*aspect,-.40),oR=vec2(.33*aspect,-.40);
 float autoL=1.5708-.36-.30*sin(t*.61),autoR=1.5708+.36+.30*sin(t*.61+.9);
 vec2 hA=vec2((uParam_left_x-.5)*aspect,uParam_left_y-.5),hB=vec2((uParam_right_x-.5)*aspect,uParam_right_y-.5);
 float pA=smoothstep(.02,.2,uParam_left_y),pB=smoothstep(.02,.2,uParam_right_y);
 bool swapHands=hA.x>hB.x;
 vec2 hL=swapHands?hB:hA,hR=swapHands?hA:hB;
 float pL=(swapHands?pB:pA)*uParam_aim,pR=(swapHands?pA:pB)*uParam_aim;
 return side==0?mix(autoL,atan(hL.y-oL.y,hL.x-oL.x),pL):mix(autoR,atan(hR.y-oR.y,hR.x-oR.x),pR);
}
void mainImage(out vec4 fragColor,in vec2 fragCoord){
 vec2 p=(fragCoord-.5*iResolution.xy)/iResolution.y;
 float aspect=iResolution.x/iResolution.y,pix=1.0/iResolution.y;
 float t=vrchPhase_speed();
 float strike=smoothstep(0.0,.85,uParam_accent);
 float s=smoke(p,t);
 float density=mix(.7,.06+1.6*s*s*s,uParam_haze);
 float count=beamCount();
 vec2 oL=vec2(-.33*aspect,-.40),oR=vec2(.33*aspect,-.40);
 vec3 beams=fan(p,oL,0,count,t,0.0,pix)+fan(p,oR,12,count,t,2.3,pix);
 vec2 dl=p-oL,dr=p-oR;
 float flare=exp(-length(dl)*55.0)+exp(-length(dr)*55.0);
 float bloom=exp(-length(dl)*9.0)+exp(-length(dr)*9.0);
 float streak=exp(-abs(dl.y)*160.0-abs(dl.x)*4.0)+exp(-abs(dr.y)*160.0-abs(dr.x)*4.0);
 float power=(.55+uParam_glow*1.0)*(1.0+1.4*strike);
 vec3 ink=uParam_color.rgb;
 vec3 c=ink*(beams.x*(.25+1.0*density)+beams.y*density*.22)*power;
 c+=mix(ink,vec3(1.0),.6)*(beams.z*1.5+flare*1.2)+ink*(bloom*.10*density+streak*.06)*power;
 fragColor=vec4(1.0-exp(-c*1.3),1.0);
}

frame.source:
// Texel i < 12: beam i of the left fan; texel 12 + i: beam i of the right fan.
void vrchFrame(in int texel,out vec4 value){
 float t=vrchPhase_speed();
 float strike=smoothstep(0.0,.85,uParam_accent);
 float count=beamCount();
 float spread=(.18+uParam_spread*.9)*(1.0+.35*strike);
 float wobble=uParam_bend+uParam_motion*.8;
 int side=texel/12;
 float fi=float(texel-12*side),sideShift=side==0?0.0:2.3;
 float k=count>1.0?fi/(count-1.0)-.5:0.0;
 float a=fanCenter(side,t)+k*spread+wobble*.09*sin(t*1.3+fi*1.7+sideShift);
 value=vec4(cos(a),sin(a),0.0,0.0);
}
